# -*- coding: utf-8 -*-
# Modelo HFSS gerado por LTA (linhas periodicas) - estrutura 'ebg_senoidal_10p'
# Executar no Ansys Electronics Desktop: Tools > Run Script...
# Unidades: mm. Trilha e terra como folhas PerfectE (sem perdas de condutor).
import ScriptEnv
ScriptEnv.Initialize("Ansoft.ElectronicsDesktop")
oDesktop.RestoreWindow()
oProject = oDesktop.NewProject()
oProject.InsertDesign("HFSS", "ebg_senoidal_10p", "DrivenModal", "")
oDesign = oProject.SetActiveDesign("ebg_senoidal_10p")
oEditor = oDesign.SetActiveEditor("3D Modeler")
oEditor.SetModelUnits(["NAME:Units Parameter", "Units:=", "mm", "Rescale:=", False])

def var(nome, valor):
    oDesign.ChangeProperty(["NAME:AllTabs", ["NAME:LocalVariableTab",
        ["NAME:PropServers", "LocalVariables"],
        ["NAME:NewProps", ["NAME:" + nome, "PropType:=", "VariableProp", "UserDef:=", True, "Value:=", valor]]]])

var("h_sub", "1.27mm")
var("h_ar", "12.7mm")

def attr(nome, material, cor, transp=0.0, solve=True):
    return ["NAME:Attributes", "Name:=", nome, "Flags:=", "", "Color:=", cor,
            "Transparency:=", transp, "PartCoordinateSystem:=", "Global", "UDMId:=", "",
            "MaterialValue:=", "\"" + material + "\"", "SolveInside:=", solve]

oDefMgr = oProject.GetDefinitionManager()
oDefMgr.AddMaterial(["NAME:substrato_lta", "CoordinateSystemType:=", "Cartesian",
    "BulkOrSurfaceType:=", 1, ["NAME:PhysicsTypes", "set:=", ["Electromagnetic"]],
    "permittivity:=", "10.2", "dielectric_loss_tangent:=", "0.0022"])

# Substrato
oEditor.CreateBox(["NAME:BoxParameters",
    "XPosition:=", "0mm", "YPosition:=", "-7.599562mm", "ZPosition:=", "0mm",
    "XSize:=", "110mm", "YSize:=", "15.199125mm", "ZSize:=", "h_sub"],
    attr("Substrato", "substrato_lta", "(143 175 143)", 0.6))

# Caixa de ar (contém o substrato)
oEditor.CreateBox(["NAME:BoxParameters",
    "XPosition:=", "0mm", "YPosition:=", "-7.599562mm", "ZPosition:=", "0mm",
    "XSize:=", "110mm", "YSize:=", "15.199125mm", "ZSize:=", "h_sub+h_ar"],
    attr("Ar", "vacuum", "(128 255 255)", 0.9))

def poligono(nome, pts):
    p = [["NAME:PLPoint", "X:=", "%.6fmm" % x, "Y:=", "%.6fmm" % y, "Z:=", "h_sub"] for x, y in pts]
    p.append(p[0])
    seg = [["NAME:PLSegment", "SegmentType:=", "Line", "StartIndex:=", i, "NoOfPoints:=", 2]
           for i in range(len(pts))]
    oEditor.CreatePolyline(["NAME:PolylineParameters", "IsPolylineCovered:=", True,
        "IsPolylineClosed:=", True, ["NAME:PolylinePoints"] + p, ["NAME:PolylineSegments"] + seg],
        attr(nome, "vacuum", "(255 128 0)"))

